#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
쓰레드 글 + 사진  (브랜치 복구 포함)

지난번에 "You are not currently on a branch" 로 멈춘 걸 고쳤습니다.
저장소를 깃허브 최신 상태로 맞춘 다음 작업합니다.

하는 일
  1) 로컬 저장소를 깃허브 main 에 다시 붙임 (detached HEAD 복구)
  2) 쓰레드 글 24편 교체 — 셀러의 장사 이야기로 열고 제품으로 증명
  3) 제품 사진 14장을 media/ 에 넣고 글에 첨부
  4) 앞으로 4주치 큐를 새 문안으로 다시 생성
  5) 오늘 아직 안 나간 글도 교체

이 파일은 저장소 폴더(= queue.csv 가 있는 폴더) 안에 두고 실행하세요.
"""

import base64, csv, json, os, subprocess, sys

ROOT = os.path.dirname(os.path.abspath(__file__))
PAYLOAD = {'.github/workflows/weekly-content.yml': '',
 'generate_content.py': '',
 'media/glove-34.jpg': '',
 'media/glove-color.jpg': '',
 'media/glove-grip.jpg': '',
 'media/glove-hang.jpg': '',
 'media/glove-veg.jpg': '',
 'media/hand-bottle.jpg': '',
 'media/hand-leaf.jpg': '',
 'media/hand-peony.jpg': '',
 'media/soap-hand.jpg': '',
 'media/soap-lemon.jpg': '',
 'media/soap-pan.jpg': '',
 'media/soap-sink.jpg': '',
 'media/soap-two.jpg': '',
 'media/soap-veg.jpg': '',
 'threads.json': ''}

FIELDS = ["date", "time", "platform", "type", "files", "caption", "status", "result"]


def run(*a):
    return subprocess.run(a, cwd=ROOT, stdout=subprocess.PIPE,
                          stderr=subprocess.STDOUT)


def out(p):
    return p.stdout.decode("utf-8", "replace").strip()


def main():
    print("쓰레드 글 + 사진")
    print("폴더:", ROOT)
    print()

    if not os.path.exists(os.path.join(ROOT, "queue.csv")):
        print("!! queue.csv 가 있는 폴더에 두고 실행하세요.")
        input("\n엔터를 누르면 닫힙니다...")
        return

    # 1) 브랜치 복구 --------------------------------------------------
    print("1) 저장소 상태 맞추는 중")
    cur = out(run("git", "rev-parse", "--abbrev-ref", "HEAD"))
    print("   현재 위치:", cur if cur != "HEAD" else "브랜치에서 떨어져 있음 (복구합니다)")

    f = run("git", "fetch", "origin", "main")
    if f.returncode != 0:
        print("   !! 깃허브에서 받아오지 못했습니다")
        print(out(f)[:600])
        print("   로그인 창이 떴는지 확인해 보세요 (Alt+Tab)")
        input("\n엔터를 누르면 닫힙니다...")
        return

    run("git", "reset", "--hard")                 # working tree 정리
    c = run("git", "checkout", "-B", "main", "origin/main")
    if c.returncode != 0:
        print("   !! 브랜치 복구 실패")
        print(out(c)[:600])
        input("\n엔터를 누르면 닫힙니다...")
        return
    print("   OK main 브랜치, 깃허브 최신 상태")

    # 2) 파일 넣기 ----------------------------------------------------
    print()
    print("2) 파일 넣는 중")
    for rel, b64 in PAYLOAD.items():
        path = os.path.join(ROOT, *rel.split("/"))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fp:
            fp.write(base64.b64decode(b64))
    print(f"   {len(PAYLOAD)}개 (사진 포함)")

    # 3) 큐 다시 만들기 -----------------------------------------------
    print()
    print("3) 앞으로 4주치 큐 생성 중")
    g = run(sys.executable, "generate_content.py", "--days", "28", "--force")
    if g.returncode != 0:
        print("   !! 실패")
        print(out(g)[:800])
        input("\n엔터를 누르면 닫힙니다...")
        return
    print("  ", out(g).replace("\n", "\n   "))

    # 4) 오늘 아직 안 나간 쓰레드 글도 교체 ---------------------------
    import datetime
    today = (datetime.datetime.utcnow() +
             datetime.timedelta(hours=9)).strftime("%Y-%m-%d")
    posts = json.load(open(os.path.join(ROOT, "threads.json"), encoding="utf-8"))
    with open(os.path.join(ROOT, "queue.csv"), encoding="utf-8-sig", newline="") as fp:
        rows = list(csv.DictReader(fp))
    todo = [r for r in rows if r["date"] == today
            and r["platform"] == "threads" and not r["status"]]
    picks = [p for p in posts if p.get("img")][:2]
    for n, r in enumerate(todo):
        if n >= len(picks):
            break
        p = picks[n]
        r["caption"] = p["text"].replace("\n", "\\n")
        r["type"] = "image"
        r["files"] = p["img"]
    with open(os.path.join(ROOT, "queue.csv"), "w",
              encoding="utf-8-sig", newline="") as fp:
        w = csv.DictWriter(fp, fieldnames=FIELDS)
        w.writeheader()
        for r in rows:
            w.writerow({k: r.get(k, "") for k in FIELDS})
    print(f"   오늘 남은 쓰레드 {len(todo)}건도 새 글로 교체")

    # 5) 올리기 -------------------------------------------------------
    print()
    print("4) 깃허브에 올리는 중")
    run("git", "config", "user.name", "wonbi")
    run("git", "config", "user.email", "wonbi@users.noreply.github.com")
    run("git", "add", "-A")
    run("git", "commit", "-m", "쓰레드 글 교체 + 제품 사진 첨부")
    p = run("git", "push", "-u", "origin", "main")
    if p.returncode != 0:
        run("git", "pull", "--rebase", "--autostash")
        p = run("git", "push", "-u", "origin", "main")

    if p.returncode == 0:
        print("   OK 올라갔습니다")
        print()
        print("   영상은 깃허브에서 다시 만들어야 합니다. 제가 이어서 돌리겠습니다.")
    else:
        print("   !! 실패")
        print(out(p)[:800])
        print("   로그인 창이 떴는지 확인해 보세요 (Alt+Tab)")

    input("\n엔터를 누르면 닫힙니다...")


if __name__ == "__main__":
    main()
